// 1. Obtener todos los registros de feedback que entran desde la base de datos
const items = $input.all();

let totalResenas = items.length;
let sumaCalidad = 0;
let sumaAtencion = 0;
let sumaTiempo = 0;
let sumaGlobal = 0;

const criticasNegativas = [];
const comentariosPositivos = [];

// 2. Iterar sobre cada fila para sumar métricas y clasificar comentarios
items.forEach(item => {
  const data = item.json;

  // Convertir a número por seguridad y sumar al acumulador
  const calidad = Number(data.calidad_sabor) || 0;
  const atencion = Number(data.atencion_mesero) || 0;
  const tiempo = Number(data.tiempo_espera) || 0;
  const global = Number(data.experiencia_global) || 0;

  sumaCalidad += calidad;
  sumaAtencion += atencion;
  sumaTiempo += tiempo;
  sumaGlobal += global;

  // Filtrar comentarios vacíos o nulos
  if (data.comentario && data.comentario.trim() !== "") {
    // Formateamos la línea dando contexto del ticket y calificaciones clave
    const textoComentario = `• [Ticket #${data.ticket_id || 'N/A'}] (Global: ${global}/5 | Sabor: ${calidad}/5 | Espera: ${tiempo}/5 | Atención: ${atencion}/5): "${data.comentario.trim()}"`;

    // Si la experiencia global es menor a 3, o el tiempo/sabor tuvieron 2 o menos, es una crítica prioritaria
    if (global <= 3 || tiempo <= 2 || calidad <= 2 || atencion <= 2) {
      criticasNegativas.push(textoComentario);
    } else {
      comentariosPositivos.push(textoComentario);
    }
  }
});

// 3. Calcular promedios finales (evitando división por cero y redondeando a 2 decimales)
const promedios = totalResenas > 0 ? {
  calidad_sabor: (sumaCalidad / totalResenas).toFixed(2),
  atencion_mesero: (sumaAtencion / totalResenas).toFixed(2),
  tiempo_espera: (sumaTiempo / totalResenas).toFixed(2),
  experiencia_global: (sumaGlobal / totalResenas).toFixed(2)
} : { calidad_sabor: 0, atencion_mesero: 0, tiempo_espera: 0, experiencia_global: 0 };

// 4. Construir un bloque de texto limpio y optimizado para el System Prompt del LLM
const reporteParaLLM = `
=== RESUMEN DE MÉTRICAS (Total de evaluaciones: ${totalResenas}) ===
- Promedio Calidad y Sabor: ${promedios.calidad_sabor} / 5.00
- Promedio Atención del Mesero: ${promedios.atencion_mesero} / 5.00
- Promedio Tiempo de Espera: ${promedios.tiempo_espera} / 5.00
- Promedio Experiencia Global: ${promedios.experiencia_global} / 5.00

=== CRÍTICAS NEGATIVAS Y ALERTAS (Prioridad alta para acciones correctivas) ===
${criticasNegativas.length > 0 ? criticasNegativas.join('\n') : 'No hay comentarios negativos registrados en este bloque.'}

=== COMENTARIOS POSITIVOS Y DESTACADOS (Para identificar fortalezas a mantener) ===
${comentariosPositivos.length > 0 ? comentariosPositivos.join('\n') : 'No hay comentarios positivos registrados en este bloque.'}
`.trim();

// 5. Retornar un único ítem con la data lista y digerida para el nodo del LLM
return [{
  json: {
    total_resenas: totalResenas,
    promedios: promedios,
    conteo_criticas: criticasNegativas.length,
    conteo_positivos: comentariosPositivos.length,
    prompt_contexto: reporteParaLLM
  }
}];
